[776]={["aftermath"]="Cairne planned to send a party to recover the carcass for its meat and hide.",["atomIDs"]={"776:description:1-84","776:description:89-212","776:description:217-235","776:description:237-297","776:description:299-391","776:objective:1-79"},["endingAtomIDs"]={"776:completion:1-10","776:completion:12-32","776:completion:37-126","776:completion:131-177"},["opening"]="Cairne set another test of service after the rites: tracking the mighty kodo Arra'chea in Mulgore. The horn would demonstrate hunting skill.",["pending"]="{actor} meant to bring Arra'chea's horn to Cairne.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the horn to Cairne.",["sourceHash"]="1c9c3b8ad541c813622c11792c29a08dbc138431b99d0f626c5ad132f4613455",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[777]={["aftermath"]="Lotwil ordered everyone to stand back while he prepared the next part of his experiment.",["atomIDs"]={"777:description:1-18","777:description:23-50","777:description:52-64","777:description:69-89","777:objective:1-32"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"777:completion:1-12","777:completion:14-61","777:completion:66-103"},["minimumStage"]=2,["objectiveSummary"]="Bring Lucien's fifth cog to Lotwil Veriatus.",["opening"]="Lucien handed over the cog and promptly took cover, inviting the courier to join him. Lotwil's feverish work waited on the small mechanical part despite his assistant's evident unease.",["pending"]="{actor} would carry the cog back to Lotwil.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the fifth cog to Lotwil.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="6a30ce39ef4781c7ec495da2181e4119baa55690aa45dc26d6f03a794c592aff",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
