[782]={["aftermath"]="Gorn accepted that the prison could now be opened for a confrontation with the drakes.",["atomIDs"]={"782:description:1-189","782:description:191-263","782:description:268-401","782:description:403-473","782:description:475-507","782:objective:1-70"},["endingAtomIDs"]={"782:completion:1-125","782:completion:127-185","782:completion:190-289","782:completion:292-358"},["opening"]="Gorn sought to sever the Horde's dishonorable wartime ties to Deathwing's lieutenants. The mercenary hired to obtain their prison's key had betrayed him and taken it.",["pending"]="{actor} intended to recover the sign from Tho'grun.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the sign to Gorn.",["sourceHash"]="fe3a435c5dbb9be5d3a7ee9961238c11389fb4b89f285d6540cefee5bb3b57a4",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[783]={["aftermath"]="McBride described a long campaign against dangers both outside the kingdom and within its weakened borders.",["atomIDs"]={"783:description:1-97","783:description:102-126","783:description:131-263","783:description:266-335","783:description:338-356","783:description:361-440","783:description:443-474","783:objective:1-27"},["endingAtomIDs"]={"783:completion:1-9","783:completion:12-29","783:completion:32-69","783:completion:74-92","783:completion:97-194","783:completion:197-283","783:completion:288-327","783:completion:330-363"},["opening"]="Northshire's guards were short of hands, with Stormwind's forces committed abroad and threats gathering closer to home. Willem directed willing volunteers into the abbey, where Marshal McBride was organizing the defense.",["pending"]="{actor} would answer the call by speaking with Marshal McBride.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported to McBride inside Northshire Abbey.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="7c7503bf3c33af5489648bff87dbedadd78cd7eec0bb079476eacae23ec43369",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[784]={["atomIDs"]={"784:description:1-171","784:description:176-233","784:description:235-367","784:description:369-411","784:description:416-499","784:objective:1-108"},["opening"]="Gar'Thok reported that Benedict's Kul Tiras reserves had retaken Tiragarde. He saw their return as a renewed threat to Durotar after the earlier invasion.",["pending"]="{actor} planned to confront Benedict's force at Tiragarde.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled Gar'Thok's assignment against the Kul Tiras force.",["sourceHash"]="ca5b88ff3293c6498ee9dff10420c5c4490039bd20bed115299143157ef55f33",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
