[793]={["aftermath"]="Gorn considered the two lieutenants removed and turned his attention toward Blackrock Spire.",["atomIDs"]={"793:description:1-120","793:description:122-225","793:description:230-315","793:description:317-362","793:description:367-434","793:description:437-498","793:objective:1-107","793:objective:112-187","793:objective:192-291"},["endingAtomIDs"]={"793:completion:1-122","793:completion:124-218"},["opening"]="Gorn described the three pillars holding the prison's runestones. Their recovery would release Blacklash and Hematus for the final reckoning.",["pending"]="{actor} planned to unlock the prison and return its captives' bindings.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the bindings and the sign to Gorn.",["sourceHash"]="8551feac293f7d20c1ff697d5b704254063759bee90f5e5403cf43056a21deee",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
