[805]={["aftermath"]="Gadrin said the cult had not appeared in the village but described evil taking root on the Echo Isles.",["atomIDs"]={"805:description:1-53","805:description:55-73","805:description:76-114","805:description:119-180","805:description:183-248","805:description:253-334","805:description:337-387","805:description:392-412","805:description:415-502","805:objective:1-44"},["endingAtomIDs"]={"805:completion:7-38","805:completion:40-149","805:completion:154-198","805:completion:200-217","805:completion:219-250","805:completion:252-268"},["opening"]="Zureetha feared the Burning Blade's presence in the Valley heralded a wider threat. She sent news to Gadrin and sought information from Sen'jin.",["pending"]="{actor} meant to report the cult's presence to Gadrin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the report at Sen'jin Village.",["sourceHash"]="b99a46354f4af7907d2902b1414151ec3d676791e749a17683a11c3f2f358bc2",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
