[808]={["aftermath"]="Gadrin declared that his brother's spirit had been freed from slavery.",["atomIDs"]={"808:description:1-69","808:description:74-141","808:description:143-157","808:description:162-201","808:description:203-274","808:description:276-362","808:description:364-419","808:description:424-434","808:description:436-481","808:description:483-497","808:description:502-510","808:objective:1-69","808:objective:74-118"},["endingAtomIDs"]={"808:completion:1-14","808:completion:16-39","808:completion:41-88"},["opening"]="Gadrin heard his dead brother in dreams. He said Zalazane bound Minshina's spirit inside a skull kept in the Echo Isles' circle of power.",["pending"]="{actor} planned to recover Minshina's skull for Gadrin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Minshina's skull to Gadrin.",["sourceHash"]="2b33574e28a906d70d81d352b30f5bc7c36a5f6425a308f0f56901c85302242e",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
